import type { Product } from "../../src/domain/product.js";

function makeProduct(
  id: number,
  title: string,
  description: string,
  category: string,
  rate: number,
  count: number,
): Product {
  return {
    id,
    title,
    description,
    category,
    price: { amount: "19.99", currency: "USD" },
    imageUrl: `https://images.example.test/${id}.jpg`,
    rating: { rate, count },
  };
}

